#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <sched.h>

#ifdef __AVX512F__
#define VW 16
#define MR 12
#define NCB 256
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
#define VW 8
#define MR 6
#define NCB 192
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif
#define NR (2 * VW)
#define KC 256
#define MAXT 64
#define SPIN_LIMIT (1L << 22)

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof v); }

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* Full MR x NR tile: C (=|+=) Apanel * Bpanel. No edge handling in here. */
static inline __attribute__((always_inline))
void kernel(int kc, const float *restrict a, const float *restrict b,
            float *restrict c, int ldc, int acc)
{
#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
    ROWS(DECL)
#undef DECL

#define PFC(i) __builtin_prefetch(c + (size_t)(i) * ldc, 1, 3); \
               __builtin_prefetch(c + (size_t)(i) * ldc + NR - 1, 1, 3);
    ROWS(PFC)
#undef PFC

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __builtin_prefetch(b + 8 * NR, 0, 3);
#if VW == 16
        __builtin_prefetch(b + 8 * NR + 16, 0, 3);
#endif
        vf b0 = *(const vf *)b;
        vf b1 = *(const vf *)(b + VW);
#define STEP(i) { float t = a[i]; c##i##_0 += t * b0; c##i##_1 += t * b1; }
        ROWS(STEP)
#undef STEP
        a += MR;
        b += NR;
    }

    if (acc) {
#define ACC(i) { float *p = c + (size_t)(i) * ldc; \
                 stu(p, ldu(p) + c##i##_0); stu(p + VW, ldu(p + VW) + c##i##_1); }
        ROWS(ACC)
#undef ACC
    } else {
#define ST(i) { float *p = c + (size_t)(i) * ldc; stu(p, c##i##_0); stu(p + VW, c##i##_1); }
        ROWS(ST)
#undef ST
    }
}

static void kernel_edge(int kc, const float *a, const float *b, float *c, int ldc,
                        int mr, int nr, int acc)
{
    float tmp[MR * NR] __attribute__((aligned(64)));
    kernel(kc, a, b, tmp, NR, 0);
    for (int i = 0; i < mr; i++) {
        float *cp = c + (size_t)i * ldc;
        const float *t = tmp + i * NR;
        if (acc)
            for (int j = 0; j < nr; j++) cp[j] += t[j];
        else
            for (int j = 0; j < nr; j++) cp[j] = t[j];
    }
}

/* Packs an mr x kc micro-panel of A (k-major, MR wide), zero-padding missing rows. */
static void pack_a(const float *A, int n, int i0, int mr, int p0, int kc, float *restrict d)
{
    const float *s = A + (size_t)i0 * n + p0;
    if (mr == MR) {
        for (int k = 0; k < kc; k++) {
#pragma GCC unroll 12
            for (int r = 0; r < MR; r++) d[r] = s[(size_t)r * n + k];
            d += MR;
        }
    } else {
        for (int k = 0; k < kc; k++) {
            int r = 0;
            for (; r < mr; r++) d[r] = s[(size_t)r * n + k];
            for (; r < MR; r++) d[r] = 0.0f;
            d += MR;
        }
    }
}

/* Packs the kc x nc block of B at (p0, j0) into NR-wide panels, zero-padding the last. */
static void pack_b(const float *B, int n, int p0, int kc, int j0, int nc, float *restrict Bp)
{
    for (int k = 0; k < kc; k++) {
        const float *s = B + (size_t)(p0 + k) * n + j0;
        float *d = Bp + (size_t)k * NR;
        int jp = 0;
        for (; jp + NR <= nc; jp += NR)
            memcpy(d + (size_t)jp * kc, s + jp, NR * sizeof(float));
        if (jp < nc) {
            float *dd = d + (size_t)jp * kc;
            int c = nc - jp;
            memcpy(dd, s + jp, (size_t)c * sizeof(float));
            memset(dd + c, 0, (size_t)(NR - c) * sizeof(float));
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, nt, gm, gn;
} job_t;

static job_t g_job;
static float g_Bp[MAXT][KC * NCB] __attribute__((aligned(64)));

static void run(int tid)
{
    job_t *j = &g_job;
    if (tid >= j->nt) return;
    const float *A = j->A, *B = j->B;
    float *C = j->C;
    int n = j->n, gm = j->gm, gn = j->gn;
    int rg = tid / gn, cg = tid % gn;

    int um = (n + MR - 1) / MR, un = (n + NR - 1) / NR;
    int r0 = (int)((long)um * rg / gm) * MR, r1 = (int)((long)um * (rg + 1) / gm) * MR;
    int c0 = (int)((long)un * cg / gn) * NR, c1 = (int)((long)un * (cg + 1) / gn) * NR;
    if (r0 > n) r0 = n;
    if (r1 > n) r1 = n;
    if (c0 > n) c0 = n;
    if (c1 > n) c1 = n;
    if (r0 >= r1 || c0 >= c1) return;

    float *Bp = g_Bp[tid];
    float Ap[MR * KC] __attribute__((aligned(64)));

    /* Balanced block sizes so there are no short trailing blocks. */
    int nkb = (n + KC - 1) / KC;
    int kcb = (n + nkb - 1) / nkb;
    int cols = c1 - c0;
    int nnb = (cols + NCB - 1) / NCB;
    int cstep = ((cols + nnb - 1) / nnb + NR - 1) / NR * NR;

    for (int jc = c0; jc < c1; jc += cstep) {
        int nc = c1 - jc < cstep ? c1 - jc : cstep;
        int nfull = nc / NR * NR;
        for (int pc = 0; pc < n; pc += kcb) {
            int kc = n - pc < kcb ? n - pc : kcb;
            int acc = pc != 0;
            pack_b(B, n, pc, kc, jc, nc, Bp);
            for (int ir = r0; ir < r1; ir += MR) {
                int mr = r1 - ir < MR ? r1 - ir : MR;
                pack_a(A, n, ir, mr, pc, kc, Ap);
                float *cc = C + (size_t)ir * n + jc;
                if (mr == MR) {
                    for (int jr = 0; jr < nfull; jr += NR)
                        kernel(kc, Ap, Bp + (size_t)jr * kc, cc + jr, n, acc);
                } else {
                    for (int jr = 0; jr < nfull; jr += NR)
                        kernel_edge(kc, Ap, Bp + (size_t)jr * kc, cc + jr, n, mr, NR, acc);
                }
                if (nfull < nc)
                    kernel_edge(kc, Ap, Bp + (size_t)nfull * kc, cc + nfull, n,
                                mr, nc - nfull, acc);
            }
        }
    }
}

/* Persistent pool. */
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static unsigned g_gen;
static int g_remaining;
static int g_pool = -1;

static void *pool_main(void *arg)
{
    int tid = (int)(long)arg;
    unsigned seen = 0;
    for (;;) {
        unsigned g;
        long spins = 0;
        while ((g = __atomic_load_n(&g_gen, __ATOMIC_ACQUIRE)) == seen) {
            if (++spins < SPIN_LIMIT) {
                cpu_relax();
            } else {
                pthread_mutex_lock(&g_mu);
                while (__atomic_load_n(&g_gen, __ATOMIC_ACQUIRE) == seen)
                    pthread_cond_wait(&g_cv, &g_mu);
                pthread_mutex_unlock(&g_mu);
                spins = 0;
            }
        }
        seen = g;
        run(tid);
        __atomic_sub_fetch(&g_remaining, 1, __ATOMIC_ACQ_REL);
    }
    return NULL;
}

static int detect_threads(void)
{
    int n = 0;
#ifdef __linux__
    cpu_set_t cs;
    if (sched_getaffinity(0, sizeof cs, &cs) == 0) n = CPU_COUNT(&cs);
#endif
    if (n <= 0) {
        long c = sysconf(_SC_NPROCESSORS_ONLN);
        n = c > 0 ? (int)c : 1;
    }
    int smt = 1;
#ifdef __linux__
    FILE *f = fopen("/sys/devices/system/cpu/cpu0/topology/thread_siblings_list", "r");
    if (f) {
        char buf[256];
        if (fgets(buf, sizeof buf, f)) {
            int count = 0;
            char *p = buf, *e;
            for (;;) {
                long a = strtol(p, &e, 10);
                if (e == p) break;
                long b = a;
                if (*e == '-') b = strtol(e + 1, &e, 10);
                count += (int)(b - a + 1);
                if (*e != ',') break;
                p = e + 1;
            }
            if (count > 1) smt = count;
        }
        fclose(f);
    }
#endif
    if (smt > 1 && n >= smt) n /= smt;
    if (n < 1) n = 1;
    if (n > MAXT) n = MAXT;
    return n;
}

static void pool_init(void)
{
    int hw = detect_threads();
    int created = 0;
    for (int t = 1; t < hw; t++) {
        pthread_t th;
        if (pthread_create(&th, NULL, pool_main, (void *)(long)t) != 0) break;
        pthread_detach(th);
        created++;
    }
    g_pool = created;
}

/* Picks a gm x gn grid minimizing per-thread compute plus A/B packing traffic. */
static void choose_grid(int n, int nt, int *pgm, int *pgn)
{
    int um = (n + MR - 1) / MR, un = (n + NR - 1) / NR;
    double best = 1e300;
    int bgm = 1, bgn = 1;
    for (int gm = 1; gm <= nt && gm <= um; gm++) {
        for (int gn = 1; gm * gn <= nt && gn <= un; gn++) {
            double rm = (double)((um + gm - 1) / gm) * MR;
            double cn = (double)((un + gn - 1) / gn) * NR;
            double chunks = (double)(((int)cn + NCB - 1) / NCB);
            double cost = rm * cn + 8.0 * (rm * chunks + cn);
            if (cost < best * 0.999) { best = cost; bgm = gm; bgn = gn; }
        }
    }
    *pgm = bgm;
    *pgn = bgn;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (g_pool < 0) pool_init();

    int nt = g_pool + 1;
    if (n < 64) nt = 1;

    int gm = 1, gn = 1;
    if (nt > 1) choose_grid(n, nt, &gm, &gn);
    nt = gm * gn;

    job_t *j = &g_job;
    j->A = A; j->B = B; j->C = C;
    j->n = n; j->nt = nt; j->gm = gm; j->gn = gn;

    if (nt == 1) {
        run(0);
        return;
    }

    __atomic_store_n(&g_remaining, g_pool, __ATOMIC_RELEASE);
    pthread_mutex_lock(&g_mu);
    __atomic_add_fetch(&g_gen, 1, __ATOMIC_ACQ_REL);
    pthread_cond_broadcast(&g_cv);
    pthread_mutex_unlock(&g_mu);

    run(0);

    while (__atomic_load_n(&g_remaining, __ATOMIC_ACQUIRE) != 0)
        cpu_relax();
}
